import json
d=json.load(open('AGENT_SEAT_ENVELOPE.json'))
def walk(o,p='',depth=0):
    if depth>3: return
    if isinstance(o,dict):
        for k,v in o.items():
            if isinstance(v,(dict,list)): print(' '*depth*2+k, type(v).__name__, len(v)); walk(v,p+'/'+k,depth+1)
            else: print(' '*depth*2+k,'=',str(v)[:200])
    elif isinstance(o,list):
        for i,v in enumerate(o[:5]):
            print(' '*depth*2+f'[{i}]'); walk(v,p,depth+1)
walk(d)
" 2>&1 | head -100

