import sys, json, bisect
sys.path.insert(0, '/private/tmp/r68/accept/install/scripts')

RD = '/private/tmp/r68/accept/install/output/research_runs/20261120T024347Z_美国_中国_欧元区_日本在12个月前_3个月前和最新一期的增长_通胀_货币政策环'
rep = json.load(open(RD + '/report.json'))
ser = {}
for st in rep.get('steps') or []:
    nm = st.get('step') or ''
    data = (st.get('envelope') or {}).get('data') or {}
    if nm.startswith('S4_history_') and data.get('series'):
        ser[nm.replace('S4_history_', '')] = data['series']

def month_last_obs(dates, values, ym):
    hi = bisect.bisect_right(dates, ym + '-31')
    j = hi - 1
    while j >= 0 and values[j] is None:
        j -= 1
    return (dates[j], values[j]) if j >= 0 else (None, None)

def eng_recompute(mid, aym, tgt, pct=True):
    s = ser.get(mid) or {}
    d0, v0 = month_last_obs(s.get('dates') or [], s.get('values') or [], aym)
    d1, v1 = month_last_obs(s.get('dates') or [], s.get('values') or [], tgt)
    if v0 is None or v1 is None:
        return None
    val = ((v1 / v0 - 1.0) * 100.0) if pct else (v1 - v0)
    return (round(val, 2), d0, v0, d1, v1)

SEGS = [('2025-03', {'3m': '2025-06', '6m': '2025-09', '12m': '2026-03'}),
        ('2022-06', {'3m': '2022-09', '6m': '2022-12', '12m': '2023-06'}),
        ('2023-10', {'3m': '2024-01', '6m': '2024-04', '12m': '2024-10'})]
for aym, hor in SEGS:
    print('== anchor', aym, '==')
    for k, tgt in hor.items():
        row = []
        for mid in ('SPX', 'DXY', 'GOLD_F'):
            r = eng_recompute(mid, aym, tgt, pct=True)
            row.append('%s %+0.2f%%' % (mid, r[0]) if r else mid + ' NA')
        r = eng_recompute('UST_10Y', aym, tgt, pct=False)
        row.append('UST_10Y %+0.2fpp (%s→%s)' % (r[0], r[1][:7], r[3][:7]) if r else 'UST NA')
        print(' ', k, tgt, ' | '.join(row))
# extra: prior-month knowable values for as_of fixes
print()
for mid, ym in [('CN_PPI_YOY', '2025-02'), ('CN_PPI_YOY', '2022-05'), ('CN_PPI_YOY', '2023-09'),
                ('EA_HICP_YOY', '2022-05'), ('EA_HICP_YOY', '2023-09'), ('EA_HICP_YOY', '2023-10'),
                ('JP_CPI_YOY', '2023-09'), ('CN_CPI_YOY', '2023-09')]:
    d, v = month_last_obs(ser.get(mid, {}).get('dates') or [], ser.get(mid, {}).get('values') or [], ym)
    print('knowable', mid, ym, '=', v, '(@', d, ')')

